/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_turno_base_set_servicio` BEFORE INSERT ON `turno_base` FOR EACH ROW BEGIN
    DECLARE v_id_servicio BIGINT;
    IF NEW.id_creador IS NOT NULL THEN
        SELECT id_servicio
        INTO v_id_servicio
        FROM servicio
        WHERE id_responsable = NEW.id_creador
        LIMIT 1;

        IF v_id_servicio IS NOT NULL THEN
            SET NEW.id_servicio = v_id_servicio;
        END IF;
    END IF;
END */;;
DELIMITER ;
